class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        height = 0

        while True:
            height += 1
            # Try both possible patterns
            # Pattern 1: Red, Blue, Red, Blue, ...
            red1 = 0
            blue1 = 0
            for row in range(1, height + 1):
                if row % 2 == 1:
                    red1 += row
                else:
                    blue1 += row

            # Pattern 2: Blue, Red, Blue, Red, ...
            red2 = 0
            blue2 = 0
            for row in range(1, height + 1):
                if row % 2 == 1:
                    blue2 += row
                else:
                    red2 += row

            # Check if either pattern works
            if (red1 <= red and blue1 <= blue) or (red2 <= red and blue2 <= blue):
                continue
            else:
                return height - 1

