class Solution:
    def minimumCoins(self, prices: List[int]) -> int:
        n = len(prices)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            # Option: purchase fruit i directly
            dp[i] = dp[i-1] + prices[i-1]

            # Option: get fruit i for free from a previous purchase
            for j in range(1, i):
                if j + j >= i:
                    dp[i] = min(dp[i], dp[j] + prices[j-1])

        return dp[n]

