        # If we have at least one one, we can start with 1  
        if one > 0:
            dp[0][0][1][0] = 1

        # Fill the DP table
        for z in range(zero + 1):
            for o in range(one + 1):
                # Skip if we're at the base case
                if z == 0 and o == 0:
                    continue

                # For each possible last element and consecutive count
                for last in range(2):
                    for consec in range(limit + 1):
                        if dp[z][o][last][consec] == 0:
                            continue

                        # Try to extend by adding a zero (if available)
                        if z < zero:
                            new_z = z + 1
                            new_o = o

                            # If the last element was 0, we continue the sequence
                            if last == 0:
                                new_consec = consec + 1
                                if new_consec <= limit:
                                    dp[new_z][new_o][0][new_consec] = (dp[new_z][new_o][0][new_consec] + dp[z][o][last][consec]) % MOD
                            else:
                                # Starting a new sequence of zeros
                                dp[new_z][new_o][0][1] = (dp[new_z][new_o][0][1] + dp[z][o][last][consec]) % MOD

                        # Try to extend by adding a one (if available)
                        if o < one:
                            new_z = z
                            new_o = o + 1

                            # If the last element was 1, we continue the sequence
                            if last == 1:
                                new_consec = consec + 1
                                if new_consec <= limit:
                                    dp[new_z][new_o][1][new_consec] = (dp[new_z][new_o][1][new_consec] + dp[z][o][last][consec]) % MOD
                            else:
                                # Starting a new sequence of ones
                                dp[new_z][new_o][1][1] = (dp[new_z][new_o][1][1] + dp[z][o][last][consec]) % MOD

        # Sum all valid states with exactly zero zeros and one ones
        result = 0
        for last in range(2):
            for consec in range(limit + 1):
                result = (result + dp[zero][one][last][consec]) % MOD

        return result

class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7

        # dp[z][o][last][consecutive] = number of ways to have z zeros, o ones, 
        # ending with 'last' (0 or 1) with 'consecutive' consecutive same elements at end
        dp = [[[[0 for _ in range(limit + 1)] for _ in range(2)] for _ in range(one + 1)] for _ in range(zero + 1)]

        # Base cases: starting with either 0 or 1
        if zero >= 1:
            dp[1][0][0][1] = 1
        if one >= 1:
            dp[0][1][1][1] = 1

        # Fill the DP table
        for z in range(zero + 1):
            for o in range(one + 1):
                for last in range(2):
                    for consecutive in range(1, limit + 1):
                        if dp[z][o][last][consecutive] == 0:
                            continue

                        # Try to add a 0 (if we haven't used all zeros)
                        if z < zero:
                            new_z = z + 1
                            new_o = o

                            if last == 0:
                                # Continue sequence of 0s - only if consecutive < limit
                                if consecutive < limit:
                                    dp[new_z][new_o][0][consecutive + 1] = (dp[new_z][new_o][0][consecutive + 1] + dp[z][o][last][consecutive]) % MOD
                                # If consecutive == limit, we can't add another 0
                            else:
                                # Start a new sequence of 0s
                                dp[new_z][new_o][0][1] = (dp[new_z][new_o][0][1] + dp[z][o][last][consecutive]) % MOD

                        # Try to add a 1 (if we haven't used all ones)
                        if o < one:
                            new_z = z
                            new_o = o + 1

                            if last == 1:
                                # Continue sequence of 1s - only if consecutive < limit
                                if consecutive < limit:
                                    dp[new_z][new_o][1][consecutive + 1] = (dp[new_z][new_o][1][consecutive + 1] + dp[z][o][last][consecutive]) % MOD
                                # If consecutive == limit, we can't add another 1
                            else:
                                # Start a new sequence of 1s
                                dp[new_z][new_o][1][1] = (dp[new_z][new_o][1][1] + dp[z][o][last][consecutive]) % MOD

        # Sum all possible final states
        result = 0
        for last in range(2):
            for consecutive in range(1, limit + 1):
                result = (result + dp[zero][one][last][consecutive]) % MOD

        return result
